func:
let username = msg.payload.wasos_username;
let password = msg.payload.wasos_password;

let auth = Buffer.from(username + ":" + password).toString("base64");

msg.headers = {
    "Authorization": "Basic " + auth
};

msg.url = global.get("parat_bridge").base_urls.wasos + "/apisec/login";

// Carry username, chatroom and optional sender through the login flow
msg.config = {
    username: username,
    chatroom_name: msg.payload.wasos_chatroom_name,
    sender_name: msg.payload.wasos_sender_name
};

return msg;
